                                let currentProjectImgList = [];
        let currentProjectImgIdx = 0;

        function openProjectModal(idx) {
            const p = projectsData[idx];
            if (!p) return;
            const pmLoc = document.getElementById('pmLocation');
            if (pmLoc) {
                if (p.cat_code === 'khuonvien3d' || !p.location) {
                    pmLoc.style.display = 'none';
                } else {
                    pmLoc.style.display = 'inline-flex';
                    document.getElementById('pmLocText').innerText = p.location;
                }
            }
            document.getElementById('pmTitle').innerText = p.title;

            let imgList = [];
            if (Array.isArray(p.imgs) && p.imgs.length > 0) {
                imgList = p.imgs;
            } else if (p.img) {
                imgList = [p.img];
            }
            currentProjectImgList = imgList;
            currentProjectImgIdx = 0;

            const rawMainImg = imgList[0] || '';
            const mainImg = (typeof optimizeModalUrl === 'function') ? optimizeModalUrl(rawMainImg, 900) : rawMainImg;
            const pmImgEl = document.getElementById('pmImg');
            if (pmImgEl) pmImgEl.src = mainImg;
            if (typeof preloadGalleryList === 'function') preloadGalleryList(imgList, 0);
            document.getElementById('pmDetailDesc').innerText = p.detail_desc || p.short_desc || '';

            // Toggle prev/next arrow visibility
            const pmPrev = document.getElementById('pmPrevBtn');
            const pmNext = document.getElementById('pmNextBtn');
            if (pmPrev && pmNext) {
                const showArrows = imgList.length > 1;
                pmPrev.style.display = showArrows ? 'flex' : 'none';
                pmNext.style.display = showArrows ? 'flex' : 'none';
            }

            let specsHtml = '';
            if (p.specs && p.specs.length) {
                for (let sIdx = 0; sIdx < p.specs.length; sIdx++) {
                    const s = p.specs[sIdx];
                    const label = s[0];
                    const val = s[1];
                    specsHtml += '<div style="background:var(--navy-dark); padding:10px 14px; border-radius:6px; border:1px solid var(--navy-light);">' +
                        '<div style="color:var(--text-silver); font-size:0.78rem; font-weight:bold; text-transform:uppercase; margin-bottom:3px;">' + label + '</div>' +
                        '<div style="color:var(--gold-light); font-size:0.92rem; font-weight:600;">' + val + '</div>' +
                    '</div>';
                }
            }
            document.getElementById('pmSpecsContainer').innerHTML = specsHtml;

            const galleryContainer = document.getElementById('pmGalleryContainer');
            if (galleryContainer) {
                if (imgList.length > 0) {
                    let galleryHtml = '<div style="display:flex; gap:8px; overflow-x:auto; padding:6px 2px 10px 2px; scrollbar-width:thin; align-items:center;">';
                    for (let i = 0; i < imgList.length; i++) {
                        const src = imgList[i];
                        const borderStyle = (i === 0) ? 'border:2px solid var(--gold-primary); opacity:1.0; transform:scale(1.04); box-shadow:0 0 8px rgba(197,160,89,0.8);' : 'border:1px solid rgba(255,255,255,0.35); opacity:0.75;';
                        galleryHtml += '<img data-src="' + src + '" data-idx="' + i + '" src="' + ktThumb(src.indexOf("/image/upload/") !== -1 ? src.replace("/image/upload/", "/image/upload/f_auto,q_auto,w_160,q_auto:eco/") : src) + '" decoding="async" style="width:80px; height:58px; object-fit:cover; border-radius:6px; cursor:pointer; flex-shrink:0; transition:all 0.2s;' + borderStyle + '" title="Ảnh thứ ' + (i+1) + '">';
                    }
                    galleryHtml += '</div>';
                    galleryContainer.innerHTML = galleryHtml;
                    galleryContainer.style.display = 'block';

                    const thumbs = galleryContainer.querySelectorAll('img[data-src]');
                    for (let t = 0; t < thumbs.length; t++) {
                        thumbs[t].onclick = (function(idx) {
                            return function(e) {
                                e.stopPropagation();
                                setProjectModalActiveImg(idx);
                            };
                        })(t);
                    }
                } else {
                    galleryContainer.innerHTML = '';
                    galleryContainer.style.display = 'none';
                }
            }

            const modal = document.getElementById('projectDetailModal');
            if (modal) modal.style.display = 'flex';
        }


        // --- Image Optimization & Preloading Engine (Instant Switching) ---
        const _ktdtlImgCache = new Map();
        function optimizeModalUrl(url, width) {
            if (!url || typeof url !== 'string') return '';
            width = width || 900;
            if (url.indexOf('/image/upload/') !== -1) {
                return reReplaceCloudinary(url, 'f_auto,q_auto,w_' + width);
            }
            return url;
        }
        function reReplaceCloudinary(url, transform) {
            // Replace existing /image/upload/f_auto... or plain /image/upload/
            return url.replace(/\/image\/upload\/(?:f_auto[^\/]*\/)?/, '/image/upload/' + transform + '/');
        }
        function preloadImageUrl(url) {
            if (!url) return;
            const optUrl = optimizeModalUrl(url, 900);
            if (_ktdtlImgCache.has(optUrl)) return;
            const img = new Image();
            img.decoding = 'async';
            img.src = optUrl;
            _ktdtlImgCache.set(optUrl, img);
            // Also cache raw URL if different
            if (optUrl !== url && !_ktdtlImgCache.has(url)) {
                const imgRaw = new Image();
                imgRaw.decoding = 'async';
                imgRaw.src = url;
                _ktdtlImgCache.set(url, imgRaw);
            }
        }
        function preloadGalleryList(imgList, startIdx) {
            if (!Array.isArray(imgList) || imgList.length === 0) return;
            startIdx = startIdx || 0;
            // Immediate priority: next 2 and prev 1
            const order = [];
            for (let offset = 1; offset < imgList.length; offset++) {
                order.push((startIdx + offset) % imgList.length);
            }
            // Preload adjacent immediately, rest staggered by 30ms
            order.forEach(function(idx, step) {
                if (step < 3) {
                    preloadImageUrl(imgList[idx]);
                } else {
                    setTimeout(function() { preloadImageUrl(imgList[idx]); }, step * 25);
                }
            });
        }
        // Preload on card hover/touchstart for instant modal opening
        document.addEventListener('mouseover', function(e) {
            const card = e.target.closest('[onclick*="openProjectModal"], [onclick*="openProductModal"], [onclick*="openGroupedProductModal"]');
            if (!card || card.dataset.preloaded) return;
            card.dataset.preloaded = '1';
            const attr = card.getAttribute('onclick') || '';
            const mProj = attr.match(/openProjectModal\((\d+)\)/);
            if (mProj && typeof projectsData !== 'undefined') {
                const p = projectsData[parseInt(mProj[1])];
                if (p && Array.isArray(p.imgs)) preloadGalleryList(p.imgs, 0);
            }
            const mProd = attr.match(/openGroupedProductModal\((\d+)\)/);
            if (mProd && typeof groupedProductsData !== 'undefined') {
                const p = groupedProductsData[parseInt(mProd[1])];
                if (p && Array.isArray(p.imgs)) preloadGalleryList(p.imgs, 0);
            }
        }, { passive: true });

