        function openProductModal(title, tag, imgData, desc, size, material, priceStr, currentIdx) {
            try {
                let imgList = [];
                if (Array.isArray(imgData)) {
                    imgList = imgData;
                } else if (typeof imgData === 'string') {
                    if (imgData.trim().startsWith('[')) {
                        try { imgList = JSON.parse(imgData); } catch(e) { imgList = [imgData]; }
                    } else {
                        imgList = [imgData];
                    }
                }

                currentProductImgList = imgList;
                currentProductImgIdx = 0;

                const mainImg = (imgList.length > 0) ? imgList[0] : '';
                const titleEl = document.getElementById('prodTitle');
                if (titleEl) titleEl.innerText = title || '';
                
                const tagEl = document.getElementById('prodTag');
                if (tagEl) tagEl.innerText = tag || 'Sản Phẩm';
                
                const imgEl = document.getElementById('prodImg');
                if (imgEl) imgEl.src = (typeof optimizeModalUrl === 'function') ? optimizeModalUrl(mainImg, 900) : mainImg;
                if (typeof preloadGalleryList === 'function') preloadGalleryList(imgList, 0);

                // Toggle prev/next arrow visibility
                const prodPrev = document.getElementById('prodPrevBtn');
                const prodNext = document.getElementById('prodNextBtn');
                if (prodPrev && prodNext) {
                    const showArrows = imgList.length > 1;
                    prodPrev.style.display = showArrows ? 'flex' : 'none';
                    prodNext.style.display = showArrows ? 'flex' : 'none';
                }

                // Gallery Thumbnails (Horizontal Row Below Main Photo - Ảnh 2)
                const galleryContainer = document.getElementById('prodGalleryContainer');
                if (galleryContainer) {
                    if (imgList.length > 0) {
                        let galleryHtml = '<div style="display:flex; gap:8px; overflow-x:auto; padding:6px 2px 10px 2px; scrollbar-width:thin; align-items:center;">';
                        for (let i = 0; i < imgList.length; i++) {
                            const src = imgList[i];
                            const borderStyle = (i === 0) ? 'border:2px solid #c5a059; opacity:1.0; transform:scale(1.04); box-shadow:0 0 8px rgba(197,160,89,0.8);' : 'border:1px solid rgba(255,255,255,0.35); opacity:0.75;';
                            galleryHtml += '<img data-src="' + src + '" data-idx="' + i + '" src="' + ktThumb(src.indexOf("/image/upload/") !== -1 ? src.replace("/image/upload/", "/image/upload/f_auto,q_auto,w_160,q_auto:eco/") : src) + '" decoding="async" style="width:80px; height:58px; object-fit:cover; border-radius:6px; cursor:pointer; flex-shrink:0; transition:all 0.2s;' + borderStyle + '" title="Ảnh thứ ' + (i+1) + '">';
                        }
                        galleryHtml += '</div>';
                        galleryContainer.innerHTML = galleryHtml;
                        galleryContainer.style.display = 'block';

                        const thumbs = galleryContainer.querySelectorAll('img[data-src]');
                        for (let i = 0; i < thumbs.length; i++) {
                            thumbs[i].onclick = (function(idx) {
                                return function(e) {
                                    e.stopPropagation();
                                    setProductModalActiveImg(idx);
                                };
                            })(i);
                        }
                    } else {
                        galleryContainer.innerHTML = '';
                        galleryContainer.style.display = 'none';
                    }
                }

                // Rich Description Paragraph (~300 words)
                const descElem = document.getElementById('prodDescPara');
                if (descElem) {
                    descElem.innerText = desc || ('Sản phẩm ' + title + ' được chế tác từ đá tự nhiên nguyên khối tuyển chọn tại làng nghề Ninh Vân, Ninh Bình. Chuẩn phong thủy Lỗ Ban.');
                }

                // Recommended Products Sidebar (Right Side)
                const recContainer = document.getElementById('prodRecommendedList');
                if (recContainer && typeof groupedProductsData !== 'undefined') {
                    let recHtml = '';
                    let recItems = [];
                    const curIdxNum = (typeof currentIdx === 'number') ? currentIdx : -1;
                    const currentCatCode = (curIdxNum >= 0 && typeof groupedProductsData[curIdxNum] !== 'undefined') ? groupedProductsData[curIdxNum].cat_code : '';
                    
                    // First try same category products (up to 10)
                    for (let i = 0; i < groupedProductsData.length; i++) {
                        const p = groupedProductsData[i];
                        if (i !== curIdxNum && p.cat_code === currentCatCode && recItems.length < 10) {
                            recItems.push({ item: p, index: i });
                        }
                    }
                    // Fill remaining with other products from next categories if needed until 10
                    if (recItems.length < 10) {
                        for (let i = 0; i < groupedProductsData.length; i++) {
                            const p = groupedProductsData[i];
                            if (i !== curIdxNum && !recItems.some(r => r.index === i) && recItems.length < 10) {
                                recItems.push({ item: p, index: i });
                            }
                        }
                    }

                    for (let i = 0; i < recItems.length; i++) {
                        const r = recItems[i];
                        const item = r.item;
                        const rIdx = r.index;
                        const rImg = (item.imgs && item.imgs[0]) ? item.imgs[0] : '';
                        const rTitle = item.title ? item.title.replace(/"/g, '&quot;') : '';
                        
                        recHtml += '<div class="rec-prod-item" onclick="openGroupedProductModal(' + rIdx + ')">' +
                            '<img src="' + ktThumb(rImg) + '" alt="' + rTitle + '" style="width:90px; height:68px; object-fit:cover; border-radius:6px; flex-shrink:0;" loading="lazy" decoding="async">' +
                            '<div style="flex:1; overflow:hidden;">' +
                                '<h4 style="color:#0b3c5d; font-size:0.9rem; margin:0 0 4px; font-weight:700; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">' + rTitle + '</h4>' +
                            '</div>' +
                        '</div>';
                    }
                    recContainer.innerHTML = recHtml;
                }

                const modal = document.getElementById('productDetailModal');
                if (modal) modal.style.display = 'flex';
            } catch(err) {
                console.error('Error in openProductModal:', err);
                const modal = document.getElementById('productDetailModal');
                if (modal) modal.style.display = 'flex';
            }
        }

