        // Setup Touch Swipe & Keyboard Navigation for Modals
        function initModalImageGestures() {
            function attachSwipe(containerId, onSwipeLeft, onSwipeRight) {
                const el = document.getElementById(containerId);
                if (!el || el._swipeAttached) return;
                el._swipeAttached = true;

                let startX = 0;
                let startY = 0;
                let startTime = 0;

                el.addEventListener('touchstart', function(e) {
                    if (e.touches.length !== 1) return;
                    startX = e.touches[0].clientX;
                    startY = e.touches[0].clientY;
                    startTime = Date.now();
                }, { passive: true });

                el.addEventListener('touchend', function(e) {
                    if (e.changedTouches.length !== 1) return;
                    const deltaX = e.changedTouches[0].clientX - startX;
                    const deltaY = e.changedTouches[0].clientY - startY;
                    const deltaTime = Date.now() - startTime;

                    // Swipe detection: horizontal > 35px, horizontal dominant (1.2x vertical), time < 650ms
                    if (Math.abs(deltaX) > 35 && Math.abs(deltaX) > Math.abs(deltaY) * 1.2 && deltaTime < 650) {
                        if (deltaX < 0) {
                            onSwipeLeft();
                        } else {
                            onSwipeRight();
                        }
                    }
                }, { passive: true });
            }

            attachSwipe('prodImgBox', function() { navigateProductModal(1); }, function() { navigateProductModal(-1); });
            attachSwipe('pmImgBox', function() { navigateProjectModal(1); }, function() { navigateProjectModal(-1); });

            if (!window._modalKeyNavAttached) {
                window._modalKeyNavAttached = true;
                document.addEventListener('keydown', function(e) {
                    const prodModal = document.getElementById('productDetailModal');
                    const projModal = document.getElementById('projectDetailModal');

                    if (prodModal && (prodModal.style.display === 'flex' || window.getComputedStyle(prodModal).display === 'flex')) {
                        if (e.key === 'ArrowRight') navigateProductModal(1);
                        else if (e.key === 'ArrowLeft') navigateProductModal(-1);
                    } else if (projModal && (projModal.style.display === 'flex' || window.getComputedStyle(projModal).display === 'flex')) {
                        if (e.key === 'ArrowRight') navigateProjectModal(1);
                        else if (e.key === 'ArrowLeft') navigateProjectModal(-1);
                    }
                });
            }
        }
        document.addEventListener('DOMContentLoaded', initModalImageGestures);
        if (document.readyState !== 'loading') {
            initModalImageGestures();
        }

        let _hdrElem = null, _scTopBtn = null, _scrollTick = false;
        function updateHeaderScrollState() {
            if (!_hdrElem) _hdrElem = document.getElementById('mainHeader');
            if (!_scTopBtn) _scTopBtn = document.getElementById('scrollTopBtn');
            const y = window.scrollY || window.pageYOffset || 0;
            if (_hdrElem) {
                if (y > 20) _hdrElem.classList.add('scrolled');
                else _hdrElem.classList.remove('scrolled');
            }
            if (_scTopBtn) {
                _scTopBtn.style.display = (y > 300) ? 'flex' : 'none';
            }
            _scrollTick = false;
        }
        function handleHeaderScroll() {
            if (!_scrollTick) {
                window.requestAnimationFrame(updateHeaderScrollState);
                _scrollTick = true;
            }
        }
        window.addEventListener('scroll', handleHeaderScroll, { passive: true });
        window.addEventListener('DOMContentLoaded', updateHeaderScrollState);

                function toggleMobileMenu() {
            const menu = document.getElementById('navMenu');
            const toggleIcon = document.querySelector('.menu-toggle i');
            if (menu) {
                const isActive = menu.classList.toggle('active');
                if (toggleIcon) {
                    if (isActive) {
                        toggleIcon.classList.remove('fa-bars');
                        toggleIcon.classList.add('fa-xmark');
                    } else {
                        toggleIcon.classList.remove('fa-xmark');
                        toggleIcon.classList.add('fa-bars');
                    }
                }
                document.body.style.overflow = isActive ? 'hidden' : '';
            }
        }
        function closeMobileMenu() {
            const menu = document.getElementById('navMenu');
            const toggleIcon = document.querySelector('.menu-toggle i');
            if (menu && menu.classList.contains('active')) {
                menu.classList.remove('active');
                if (toggleIcon) {
                    toggleIcon.classList.remove('fa-xmark');
                    toggleIcon.classList.add('fa-bars');
                }
                document.body.style.overflow = '';
            }
        }
        document.addEventListener('DOMContentLoaded', function() {
            const navLinks = document.querySelectorAll('#navMenu .nav-link');
            navLinks.forEach(function(link) {
                link.addEventListener('click', function() {
                    closeMobileMenu();
                });
            });
        });

