        /* AUTO BACKGROUND SLIDER FOR HERO AND PAGE BANNERS (7s SPEED) */
        let bgSlideIndex = 0;
        function initBgSliders() {
            const heroSlides = document.querySelectorAll('.hero-bg-slide');
            if (heroSlides.length > 1) {
                setInterval(() => {
                    heroSlides[bgSlideIndex].classList.remove('active');
                    bgSlideIndex = (bgSlideIndex + 1) % heroSlides.length;
                    heroSlides[bgSlideIndex].classList.add('active');
                }, 7000);
            }

            const bannerSlides = document.querySelectorAll('.page-banner-slide');
            if (bannerSlides.length > 1) {
                let bannerIndex = 0;
                setInterval(() => {
                    bannerSlides[bannerIndex].classList.remove('active');
                    bannerIndex = (bannerIndex + 1) % bannerSlides.length;
                    bannerSlides[bannerIndex].classList.add('active');
                }, 7000);
            }
        }
        window.addEventListener('load', initBgSliders);
